INSERT INTO kb_facts (id, category, statement_zh, sensitivity, verification_status, visibility, source_ids_json, evidence_hint, tags_json) VALUES
('profile_plain_crossroads','族群簡介','卑南族位於多族群交會的平原地帶，長期與外界文化接觸，同時仍維繫傳統文化與生活。','low','verified_public','public',CAST('["cip_puyuma_profile"]' AS JSON),'CIP 卑南族頁：族群簡介',CAST('[]' AS JSON)),
('profile_age_house_core','社會制度','卑南族社會以嚴謹的年齡階級組織與會所制度聞名，這兩者是理解部落公共生活的重要基礎。','medium','verified_public','public_summary_only',CAST('["cip_puyuma_profile"]' AS JSON),NULL,CAST('[]' AS JSON)),
('profile_annual_rituals_overview','祭儀','卑南族現今仍有小米除草完工、小米收穫、少年年祭、年祭與大獵祭等年度慶典，其中年祭規模最大。','medium','verified_public','public_summary_only',CAST('["cip_puyuma_profile"]' AS JSON),NULL,CAST('[]' AS JSON)),
('name_puyuma_pinuyumayan_distinction','正名','Puyuma 源自南王部落名稱；為避免族稱與部落名混用，近年有族人提倡以 Pinuyumayan 作為卑南族族稱。','low','verified_public','public',CAST('["cip_puyuma_profile"]' AS JSON),NULL,CAST('[]' AS JSON)),
('origin_bamboo_stone','起源敘事','卑南族起源敘事常見「竹生」與「石生」兩大說法，前者以卑南社/南王為中心，後者以知本社為中心。','medium','verified_public','public_summary_only',CAST('["cip_puyuma_profile"]' AS JSON),NULL,CAST('[]' AS JSON)),
('settlement_core_area','部落地理','現代卑南族主要以臺東平原的臺東市、卑南鄉一帶為核心，也有族人居住成功鎮、太麻里鄉或移居都市。','low','verified_public','public',CAST('["cip_puyuma_profile"]' AS JSON),NULL,CAST('[]' AS JSON)),
('community_list_public','部落地理','公開資料列出知本、建和、南王、寶桑、利嘉、泰安、上賓朗、下賓朗、初鹿、龍過脈等卑南族主要部落脈絡。','low','verified_public','public',CAST('["cip_puyuma_profile"]' AS JSON),NULL,CAST('[]' AS JSON)),
('agriculture_millet_to_rice','產業','卑南族早期農作以小米為重要作物，後來也有禾、麻、菽、麥等作物；水稻耕作技術在歷史敘事中與卑南王 Pinadray 有關。','low','verified_public','public',CAST('["cip_puyuma_profile"]' AS JSON),NULL,CAST('[]' AS JSON)),
('modern_economic_crops','產業','1960年代以後，部分卑南族地區的作物轉向釋迦、荖葉等經濟作物。','low','verified_public','public',CAST('["cip_puyuma_profile"]' AS JSON),NULL,CAST('[]' AS JSON)),
('traditional_food_staples','飲食','卑南族傳統飲食包含粟、旱稻、甘薯、芋頭，以及狩獵、河川魚貝取得的蛋白質來源。','low','verified_public','public',CAST('["cip_puyuma_profile"]' AS JSON),NULL,CAST('[]' AS JSON)),
('festival_food_shell_ginger','飲食','月桃葉包裹的糯米粉糰、鹹豬肉做成的月桃小米或糯米粿粽，是公開介紹中常見的卑南族慶典食物代表。','low','verified_public','public',CAST('["cip_puyuma_profile"]' AS JSON),NULL,CAST('[]' AS JSON)),
('betel_nut_role','飲食/祭祀','檳榔在卑南族生活與祭祀中具有重要性，既是日常生活中的食用物，也可作為祭祀物品。','medium','verified_public','public_summary_only',CAST('["cip_puyuma_profile"]' AS JSON),NULL,CAST('[]' AS JSON)),
('clothing_colors_patterns','服飾','卑南族傳統服飾以麻為材料，常見紅、黃、綠並搭配黑白色，呈現多層次菱形紋路與十字繡花形紋。','low','verified_public','public',CAST('["cip_puyuma_profile"]' AS JSON),NULL,CAST('[]' AS JSON)),
('clothing_social_identity','服飾/社會身分','卑南族服飾可區分性別與年齡階級，並表現社會身分與社會關係。','medium','verified_public','public_summary_only',CAST('["cip_puyuma_profile"]' AS JSON),NULL,CAST('[]' AS JSON)),
('wreath_social_meaning','服飾/祭典','祭典花環可用於族人與來賓，花環數量也可象徵友誼與社交關係；但成年會所服役期男子與守喪者只戴蕨類草環。','medium','verified_public','public_summary_only',CAST('["cip_puyuma_profile"]' AS JSON),NULL,CAST('[]' AS JSON)),
('weaving_bamboo_rattan','工藝','卑南族擅長藤竹編，公開資料提及方格編、人字編、六角編，以及藤籃、藤包、背簍、竹杯、煙斗與陷阱等物件。','low','verified_public','public',CAST('["cip_puyuma_profile"]' AS JSON),NULL,CAST('[]' AS JSON)),
('shell_ginger_mat','工藝','月桃葉編織蓆子具冬暖夏涼特性，是卑南族日常躺臥休息使用的編織品之一。','low','verified_public','public',CAST('["cip_puyuma_profile"]' AS JSON),NULL,CAST('[]' AS JSON)),
('architecture_categories','建築','卑南族傳統建築包括住屋、會所、祖靈屋；建築使用權限可分為公有與私有。','medium','verified_public','public_summary_only',CAST('["cip_puyuma_profile"]' AS JSON),NULL,CAST('[]' AS JSON)),
('architecture_public_private','建築','公有建築可包含會所、祖靈屋、瞭望臺；私有建築可包含住家、穀倉或女巫師專用祖靈屋。','high','verified_public','public_summary_only',CAST('["cip_puyuma_profile"]' AS JSON),NULL,CAST('[]' AS JSON)),
('house_structure','建築','傳統住屋可為茅草蓋頂、竹片為牆的長方形建築，內部沿牆設編床，前方設爐灶，後方可作穀倉。','medium','verified_public','public_summary_only',CAST('["cip_puyuma_profile"]' AS JSON),NULL,CAST('[]' AS JSON)),
('mens_house_training_age','會所/年齡階級','卑南族男子約12、13歲進入會所生活，接受體能、狩獵等教育訓練，直到結婚後才離開。','medium','verified_public','public_summary_only',CAST('["cip_puyuma_profile"]' AS JSON),NULL,CAST('[]' AS JSON)),
('mens_house_two_types','會所/建築','卑南族會所依年齡階級可分為少年會所與成年會所，兩者建築形制與生活訓練功能不同。','medium','verified_public','public_summary_only',CAST('["cip_puyuma_profile"]' AS JSON),NULL,CAST('[]' AS JSON)),
('ancestral_house_function','祖靈屋','祖靈屋是氏族祭祀場所，祖先祭祀與生命禮俗多與祖靈屋相關；涉及配置與儀式時需審核後才可公開。','high','verified_public','public_summary_only',CAST('["cip_puyuma_profile"]' AS JSON),NULL,CAST('[]' AS JSON)),
('music_poetic_narrative','音樂歌謠','公開介紹指出卑南族音樂節奏明確、歌詞具敘事性，整體呈現詩歌意境。','low','verified_public','public',CAST('["cip_puyuma_profile"]' AS JSON),NULL,CAST('[]' AS JSON)),
('music_function_categories','音樂歌謠','卑南族歌謠可依功能分為祭儀歌謠、休閒工作歌謠、社會時代歌謠等類型。','low','verified_public','public',CAST('["cip_puyuma_profile"]' AS JSON),NULL,CAST('[]' AS JSON)),
('music_public_figures','現代音樂','公開介紹列舉陸森寶、胡德夫、陳建年、紀曉君、張惠妹、陳明仁、桑布依等卑南族音樂/演藝相關人物。','low','verified_public','public',CAST('["cip_puyuma_profile"]' AS JSON),NULL,CAST('[]' AS JSON)),
('dance_role_difference','舞蹈','卑南族舞蹈反映男女與年齡角色差異，跳舞時需遵守個人社會身分所對應的舞步。','medium','verified_public','public_summary_only',CAST('["cip_puyuma_profile"]' AS JSON),NULL,CAST('[]' AS JSON)),
('shield_dance_spiritual_step','舞蹈','公開介紹提及猴祭時的舞步、勇士持盾牌的舞步，以及具感恩、賜福、守護部落意義的精神舞步。','medium','verified_public','public_summary_only',CAST('["cip_puyuma_profile"]' AS JSON),NULL,CAST('[]' AS JSON)),
('language_regional_variation','族語','卑南語因部落區位與族群接觸經驗而有差異，例如知本受排灣族、魯凱族語影響，北部卑南部落受阿美族語發音方式影響。','low','verified_public','public',CAST('["cip_puyuma_profile"]' AS JSON),NULL,CAST('[]' AS JSON)),
('kinship_matrilineal_summary','親屬制度','卑南族傳統婚姻家庭以母系大家族制為原則，重視母系家系、本家與宗家觀念；現代運作已有變化。','high','verified_public','public_summary_only',CAST('["cip_puyuma_profile"]' AS JSON),NULL,CAST('[]' AS JSON)),
('kinship_inheritance_marriage','親屬制度','公開介紹指出傳統上家族氏名與家屋財產由長女繼承，居住方式以男子入居女方家庭為原則，但現代從妻居已相當少見。','high','verified_public','public_summary_only',CAST('["cip_puyuma_profile"]' AS JSON),NULL,CAST('[]' AS JSON)),
('leadership_ayawan_rahan','部落制度','卑南族傳統部落政治領袖 ayawan 負責重大事件協調；祭司 rahan 掌管祭祀禮儀並需熟知曆法、氣象、歷史、歌謠與舞蹈。','high','verified_public','public_summary_only',CAST('["cip_puyuma_profile"]' AS JSON),NULL,CAST('[]' AS JSON)),
('shaman_role_public_summary','信仰/巫師','公開介紹指出巫師 na temaramaw 可為男女，與祈福、治病、驅邪等照護需求相關；平台僅可公開摘要，不得產生作法教學。','high','verified_public','public_summary_only',CAST('["cip_puyuma_profile"]' AS JSON),NULL,CAST('[]' AS JSON)),
('age_grade_training_stages','年齡階級','公開介紹指出少年約12、13歲進入少年會所，17、18歲轉入成年會所；訓練包含體能、知識、競走、摔角、野外求生與狩獵等。','medium','verified_public','public_summary_only',CAST('["cip_puyuma_profile"]' AS JSON),NULL,CAST('[]' AS JSON)),
('revitalization_1991','文化復振','公開介紹指出1991年前後，知本、初鹿與南王等部落建新會所、成立青年會或文化工作協會，推動尋根與母語復振。','low','verified_public','public',CAST('["cip_puyuma_profile"]' AS JSON),NULL,CAST('[]' AS JSON)),
('spiritual_biruwa','傳統信仰','卑南族傳統信仰認為自然、天地、四方、祖先與死者之靈等皆存在，神靈稱為 biruwa。','high','verified_public','public_summary_only',CAST('["cip_puyuma_profile"]' AS JSON),NULL,CAST('[]' AS JSON)),
('divination_public_summary','傳統信仰','公開介紹提到卑南族巫術中有占卜行為，並以夢兆與鳥占為主；此內容僅適合摘要，不可操作化。','high','verified_public','public_summary_only',CAST('["cip_puyuma_profile"]' AS JSON),NULL,CAST('[]' AS JSON)),
('ritual_categories_agriculture_life','祭儀分類','卑南族傳統信仰祭典可概分為農業相關歲時祭儀，以及按個人生命歷程進行的生命禮俗。','medium','verified_public','public_summary_only',CAST('["cip_puyuma_profile"]' AS JSON),NULL,CAST('[]' AS JSON)),
('ritual_calendar_public','祭儀時間軸','公開介紹列出3月婦女除草完工慶、4月祖先登陸與發祥地祭祖、7月小米收穫祭、12月年祭等年度脈絡；實際日期仍需依部落公告。','medium','verified_public','public_summary_only',CAST('["cip_puyuma_profile"]' AS JSON),NULL,CAST('[]' AS JSON)),
('women_weeding_detail_public','祭儀','婦女除草完工慶與農事團體、女巫師祈福、婦女團結、荖葉藤禮物、會餐與活動相關；公開平台只作摘要。','high','verified_public','public_summary_only',CAST('["cip_puyuma_profile"]' AS JSON),NULL,CAST('[]' AS JSON)),
('ancestral_landing_rite_public','祭儀','知本、建和部落每年4月會由祭司與女巫師帶領族人至祖先登陸地祭祀歷代祖先，具有慎終追遠意義。','high','verified_public','public_summary_only',CAST('["cip_puyuma_profile"]' AS JSON),NULL,CAST('[]' AS JSON)),
('millet_harvest_public','祭儀','小米收穫祭以家族為單位，公開介紹提及3至7天活動、祭司夢占與驅邪、婦女小米田祭品及收割儀式等；平台不公開操作步驟。','high','verified_public','public_summary_only',CAST('["cip_puyuma_profile"]' AS JSON),NULL,CAST('[]' AS JSON)),
('swing_millet_symbolism','祭儀/活動','部分部落在小米收穫祭期間於會所廣場搭設鞦韆架，公開介紹指出盪得越高象徵祈願隔年小米長得更高更多。','medium','verified_public','public_summary_only',CAST('["cip_puyuma_profile"]' AS JSON),NULL,CAST('[]' AS JSON)),
('annual_festival_three_weeks','年祭','年祭是舊年尾、新年頭之間的活動，公開介紹指出其包含猴祭、大獵祭等活動，前後可接近三週。','medium','verified_public','public_summary_only',CAST('["cip_puyuma_profile"]' AS JSON),NULL,CAST('[]' AS JSON)),
('monkey_rite_symbolic_modern','少年年祭/猴祭','猴祭傳統上與少年膽識訓練有關；現代公開活動已改以草猴等象徵物代替真猴。','high','verified_public','public_summary_only',CAST('["cip_puyuma_profile"]' AS JSON),NULL,CAST('[]' AS JSON)),
('hunting_rite_modern','大獵祭','大獵祭與男性成年儀式、野外求生與狩獵技能傳承相關；現代已改為定點活動，公開介紹以12月27日至31日脈絡說明。','high','verified_public','public_summary_only',CAST('["cip_puyuma_profile"]' AS JSON),NULL,CAST('[]' AS JSON)),
('joint_annual_festival_1982','聯合年祭','公開介紹指出卑南族各部落自1982年起逐漸發展出聯合年祭，由部落輪流舉辦，成為部落交誼與凝聚民族意識的重要活動。','medium','verified_public','public_summary_only',CAST('["cip_puyuma_profile"]' AS JSON),NULL,CAST('[]' AS JSON)),
('formosanbank_epark_structure','族語語料','FormosanBank 的 ePark 資料包含 ePark_1、ePark_2、ePark_3 等來源資料，並整理為 FormosanBank XML 格式，可作族語教材與音檔索引依據。','low','verified_public','public',CAST('["formosanbank_epark_readme"]' AS JSON),NULL,CAST('[]' AS JSON)),
('formosanbank_puyuma_dialects','族語語料','FormosanBank ePark dialects.csv 將 38 至 41 對應為 Nanwang_Puyuma、Zhiben_Puyuma、Xiqun_Puyuma、Jianhe_Puyuma。','low','verified_public','public',CAST('["formosanbank_dialects_csv"]' AS JSON),NULL,CAST('[]' AS JSON)),
('history_japanese_classification_pinuyumayan','歷史分類','公開資料指出，十九世紀末進入日本殖民統治時期後，卑南族在民族文化分類上被稱為 Pinuyumayan，並因主要有八個部落而被稱為「八社蕃」；平台只能將「八社」作歷史用語，不可作正式分類。','medium','verified_public','public_summary_only',CAST('["cip_puyuma_profile"]' AS JSON),'CIP 卑南族頁：美麗的家園，日治時期分類與八社蕃歷史用語',CAST('[]' AS JSON)),
('migration_hengchun_sukaro_public','歷史遷徙','公開資料指出，十八世紀有一部分卑南族氏族遷居恆春半島並發展出稱為「斯卡羅」（sukaro）的歷史脈絡；此主題涉及跨族群歷史，平台應以來源摘要呈現並標記待專題審核。','medium','verified_public','public_summary_only',CAST('["cip_puyuma_profile"]' AS JSON),'CIP 卑南族頁：美麗的家園，恆春半島與斯卡羅段落',CAST('[]' AS JSON)),
('urban_migration_modern_fields','現代發展','公開資料指出，目前有不少卑南族人離開東部到都市發展，並活躍於各領域；平台可建立「都會族人與現代發展」內容分類，但人物條目需另行來源查證。','low','verified_public','public',CAST('["cip_puyuma_profile"]' AS JSON),'CIP 卑南族頁：美麗的家園，都市發展段落',CAST('[]' AS JSON)),
('rice_technology_pinadray_public','產業/歷史','公開資料將十八世紀水稻耕作技術與器物的引進，連結到卑南王 Pinadray 的歷史敘事；此類歷史人物敘事應標示來源並避免過度擴寫。','medium','verified_public','public_summary_only',CAST('["cip_puyuma_profile"]' AS JSON),'CIP 卑南族頁：生活圖像—產業',CAST('[]' AS JSON)),
('male_clothing_parts_public','服飾','公開資料列出男子盛裝可包含上衣、黑短褲、套褲、檳榔袋、腰袋等，盛裝時也可佩刀並配戴琉璃珠或銀飾；平台應以服飾知識卡呈現，不替代部落穿著規範。','low','verified_public','public',CAST('["cip_puyuma_profile"]' AS JSON),'CIP 卑南族頁：生活圖像—服飾',CAST('[]' AS JSON)),
('young_women_clothing_public','服飾','公開資料提到適婚年齡少女服飾包括頭巾、上衣、肚兜、腰裙、綁腿等；平台可作為服飾元素資料，但不自行判斷個人身分。','low','verified_public','public',CAST('["cip_puyuma_profile"]' AS JSON),'CIP 卑南族頁：生活圖像—服飾',CAST('[]' AS JSON)),
('leader_priest_shaman_clothing_public','服飾/身分','公開資料指出傳統領袖與祭師盛裝另有羽冠與肩袋，女靈媒或巫師另有肩飾；平台可作摘要，但不得產生身分判定或儀式穿著教學。','medium','verified_public','public_summary_only',CAST('["cip_puyuma_profile"]' AS JSON),'CIP 卑南族頁：生活圖像—服飾',CAST('[]' AS JSON)),
('architecture_private_granary_public','建築','公開資料將住家、穀倉或女巫師專用祖靈屋列入私有建築類；涉及女巫師祖靈屋配置與神聖方位時，平台僅可保留摘要並需社群審核。','high','verified_public','public_summary_only',CAST('["cip_puyuma_profile"]' AS JSON),'CIP 卑南族頁：生活圖像—建築',CAST('[]' AS JSON)),
('house_status_scale_public','建築/社會身分','公開資料提到傳統家屋規模大小與屋主社會地位相關，部落領導人直系家族家屋較大，旁系血親與一般家屋較小；平台應避免將此用於現代個人身分判斷。','medium','verified_public','public_summary_only',CAST('["cip_puyuma_profile"]' AS JSON),'CIP 卑南族頁：生活圖像—建築—住屋',CAST('[]' AS JSON)),
('musical_categories_detail_public','音樂歌謠','公開資料將卑南族歌謠分為祭儀歌謠、休閒工作歌謠與社會時代歌謠，並舉例猴祭、大獵祭、年祭歌謠以及婦女工作團工作歌等。','medium','verified_public','public_summary_only',CAST('["cip_puyuma_profile"]' AS JSON),'CIP 卑南族頁：生活圖像—音樂跟歌謠',CAST('[]' AS JSON)),
